class Solution:
    def smallerOppositeParity(self, nums):
        n = len(nums)
        ans = [0] * n
        for i in range(n):
            c = 0
            for j in range(i + 1, n):
                if nums[j] < nums[i] and (nums[i] ^ nums[j]) & 1:
                    c += 1
            ans[i] = c
        return ans

