    def smallerOppositeParity(self, nums):
        vals = sorted(set(nums))
        m = len(vals)
        rank = {v: i + 1 for i, v in enumerate(vals)}
        bitE = [0] * (m + 1)
        bitO = [0] * (m + 1)
        def add(b, i):
            while i <= m:
                b[i] += 1
                i += i & -i
        def qry(b, i):
            s = 0
            while i > 0:
                s += b[i]
                i -= i & -i
            return s
        ans = [0] * len(nums)
        for i in range(len(nums) - 1, -1, -1):
            w = rank[nums[i]]
            ans[i] = qry(bitO if nums[i] % 2 == 0 else bitE, w - 1)
            add(bitE if nums[i] % 2 == 0 else bitO, w)
        return ans

