class Solution {
    public int[] smallerOppositeParity(int[] nums) {
        int n = nums.length;
        int[] s = nums.clone();
        Arrays.sort(s);
        int m = 0;
        for (int i = 0; i < n; i++)
            if (i == 0 || s[i] != s[i-1]) s[m++] = s[i];
        int[] bitE = new int[m + 1], bitO = new int[m + 1], ans = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            int w = Arrays.binarySearch(s, 0, m, nums[i]) + 1;
            int[] q = nums[i] % 2 == 1 ? bitE : bitO;
            int[] ins = nums[i] % 2 == 1 ? bitO : bitE;
            int res = 0;
            for (int j = w - 1; j > 0; j -= j & -j) res += q[j];
            for (int j = w; j <= m; j += j & -j) ins[j]++;
            ans[i] = res;
        }
        return ans;
    }
}

